// AdminServiceHandler is an implementation of the kiln.api.v1.AdminService service.
type AdminServiceHandler interface {
	// GetAdminBinding 返回管理员绑定的 GitHub 账号，以及 Dashboard 是否允许用 admin token 登录。
	GetAdminBinding(context.Context, *connect.Request[v1.GetAdminBindingRequest]) (*connect.Response[v1.GetAdminBindingResponse], error)
	// SetTokenLogin 开启或关闭 Dashboard 的 admin token 登录；关闭前必须先绑定 GitHub 账号。CLI 不受影响。
	SetTokenLogin(context.Context, *connect.Request[v1.SetTokenLoginRequest]) (*connect.Response[v1.SetTokenLoginResponse], error)
	// UnbindAdmin 解除管理员绑定的 GitHub 账号，同时恢复 Dashboard 的 admin token 登录。
	UnbindAdmin(context.Context, *connect.Request[v1.UnbindAdminRequest]) (*connect.Response[v1.UnbindAdminResponse], error)
	CreateEnrollToken(context.Context, *connect.Request[v1.CreateEnrollTokenRequest]) (*connect.Response[v1.CreateEnrollTokenResponse], error)
	// ListRunners 返回 CI Runner（kiln-runner）；AI Runner 见 ListAIRunners（PLAN #30.9）。
	ListRunners(context.Context, *connect.Request[v1.ListRunnersRequest]) (*connect.Response[v1.ListRunnersResponse], error)
	ListAIRunners(context.Context, *connect.Request[v1.ListAIRunnersRequest]) (*connect.Response[v1.ListAIRunnersResponse], error)
	RevokeRunner(context.Context, *connect.Request[v1.RevokeRunnerRequest]) (*connect.Response[v1.RevokeRunnerResponse], error)
	// DeleteRunner 删除已吊销、没有未结束任务的 Runner：从列表中移除，名称可以重新注册；它的尝试记录保留并记下名称。
	DeleteRunner(context.Context, *connect.Request[v1.DeleteRunnerRequest]) (*connect.Response[v1.DeleteRunnerResponse], error)
	DrainRunner(context.Context, *connect.Request[v1.DrainRunnerRequest]) (*connect.Response[v1.DrainRunnerResponse], error)
	// GetRunnerCache 返回 Runner 最近一次上报的缓存清单、上一次清理的结果和清理请求（PLAN #8.3）。
	GetRunnerCache(context.Context, *connect.Request[v1.GetRunnerCacheRequest]) (*connect.Response[v1.GetRunnerCacheResponse], error)
	// PurgeRunnerCache 预览（dry_run）或发起一次缓存清理：Runner 在没有正在执行的 job 时执行。
	PurgeRunnerCache(context.Context, *connect.Request[v1.PurgeRunnerCacheRequest]) (*connect.Response[v1.PurgeRunnerCacheResponse], error)
	ListRepos(context.Context, *connect.Request[v1.ListReposRequest]) (*connect.Response[v1.ListReposResponse], error)
	// SyncInstallations 刷新仓库目录：列出 App 的 installation 和仓库（不读取分支、tag、PR）。只在用户显式操作时调用。
	SyncInstallations(context.Context, *connect.Request[v1.SyncInstallationsRequest]) (*connect.Response[v1.SyncInstallationsResponse], error)
	// ReconcileRepo 对一个仓库补对账：比较它的分支、tag 和打开的 PR，补上漏掉的 webhook（PLAN #7.3）。
	ReconcileRepo(context.Context, *connect.Request[v1.ReconcileRepoRequest]) (*connect.Response[v1.ReconcileRepoResponse], error)
	BumpCacheSalt(context.Context, *connect.Request[v1.BumpCacheSaltRequest]) (*connect.Response[v1.BumpCacheSaltResponse], error)
	ListRuns(context.Context, *connect.Request[v1.ListRunsRequest]) (*connect.Response[v1.ListRunsResponse], error)
	GetRun(context.Context, *connect.Request[v1.GetRunRequest]) (*connect.Response[v1.GetRunResponse], error)
	CancelRun(context.Context, *connect.Request[v1.CancelRunRequest]) (*connect.Response[v1.CancelRunResponse], error)
	RerunRun(context.Context, *connect.Request[v1.RerunRunRequest]) (*connect.Response[v1.RerunRunResponse], error)
	RerunJob(context.Context, *connect.Request[v1.RerunJobRequest]) (*connect.Response[v1.RerunJobResponse], error)
	Dispatch(context.Context, *connect.Request[v1.DispatchRequest]) (*connect.Response[v1.DispatchResponse], error)
	// TriggerAIReview 手动触发一次 AI 审计：审计指定的 commit（ref 或 sha），仓库需要有 .kiln/agent/config.yml。
	TriggerAIReview(context.Context, *connect.Request[v1.TriggerAIReviewRequest]) (*connect.Response[v1.TriggerAIReviewResponse], error)
	// AI 请求（审计、开发，PLAN #30.9）：列出、详情（含各平台任务）、取消、重跑审计请求、读取任务的日志。
	ListAIRequests(context.Context, *connect.Request[v1.ListAIRequestsRequest]) (*connect.Response[v1.ListAIRequestsResponse], error)
	GetAIRequest(context.Context, *connect.Request[v1.GetAIRequestRequest]) (*connect.Response[v1.GetAIRequestResponse], error)
	CancelAIRequest(context.Context, *connect.Request[v1.CancelAIRequestRequest]) (*connect.Response[v1.CancelAIRequestResponse], error)
	RerunAIRequest(context.Context, *connect.Request[v1.RerunAIRequestRequest]) (*connect.Response[v1.RerunAIRequestResponse], error)
	GetAITaskLog(context.Context, *connect.Request[v1.GetAITaskLogRequest]) (*connect.Response[v1.GetAITaskLogResponse], error)
	// AI 开发（PLAN #26.11）：从 GitHub 全量同步任务池、暂停 / 恢复仓库的新领取、列出工作项、终止或重试一个工作项。
	SyncAIDev(context.Context, *connect.Request[v1.SyncAIDevRequest]) (*connect.Response[v1.SyncAIDevResponse], error)
	PauseAIDev(context.Context, *connect.Request[v1.PauseAIDevRequest]) (*connect.Response[v1.PauseAIDevResponse], error)
	ListWorkItems(context.Context, *connect.Request[v1.ListWorkItemsRequest]) (*connect.Response[v1.ListWorkItemsResponse], error)
	StopWorkItem(context.Context, *connect.Request[v1.StopWorkItemRequest]) (*connect.Response[v1.StopWorkItemResponse], error)
	RetryWorkItem(context.Context, *connect.Request[v1.RetryWorkItemRequest]) (*connect.Response[v1.RetryWorkItemResponse], error)
	GetJobLog(context.Context, *connect.Request[v1.GetJobLogRequest]) (*connect.Response[v1.GetJobLogResponse], error)
	SetSecret(context.Context, *connect.Request[v1.SetSecretRequest]) (*connect.Response[v1.SetSecretResponse], error)
	DeleteSecret(context.Context, *connect.Request[v1.DeleteSecretRequest]) (*connect.Response[v1.DeleteSecretResponse], error)
	ListSecrets(context.Context, *connect.Request[v1.ListSecretsRequest]) (*connect.Response[v1.ListSecretsResponse], error)
	SetVariable(context.Context, *connect.Request[v1.SetVariableRequest]) (*connect.Response[v1.SetVariableResponse], error)
	DeleteVariable(context.Context, *connect.Request[v1.DeleteVariableRequest]) (*connect.Response[v1.DeleteVariableResponse], error)
	ListVariables(context.Context, *connect.Request[v1.ListVariablesRequest]) (*connect.Response[v1.ListVariablesResponse], error)
	UpsertEnvironment(context.Context, *connect.Request[v1.UpsertEnvironmentRequest]) (*connect.Response[v1.UpsertEnvironmentResponse], error)
	DeleteEnvironment(context.Context, *connect.Request[v1.DeleteEnvironmentRequest]) (*connect.Response[v1.DeleteEnvironmentResponse], error)
	ListEnvironments(context.Context, *connect.Request[v1.ListEnvironmentsRequest]) (*connect.Response[v1.ListEnvironmentsResponse], error)
	// 账号级 npm 配置（PLAN #27.2）：release.npm 发布到 @<scope>/<name>，token 只写不读。
	SetNpmAccount(context.Context, *connect.Request[v1.SetNpmAccountRequest]) (*connect.Response[v1.SetNpmAccountResponse], error)
	DeleteNpmAccount(context.Context, *connect.Request[v1.DeleteNpmAccountRequest]) (*connect.Response[v1.DeleteNpmAccountResponse], error)
	ListNpmAccounts(context.Context, *connect.Request[v1.ListNpmAccountsRequest]) (*connect.Response[v1.ListNpmAccountsResponse], error)
	// 外部设计文档绑定：把仓库关联到第三方文档集（首期 Outline），API token 只写不读、由 Server 加密保存。
	ListDocBindings(context.Context, *connect.Request[v1.ListDocBindingsRequest]) (*connect.Response[v1.ListDocBindingsResponse], error)
	BindDocCollection(context.Context, *connect.Request[v1.BindDocCollectionRequest]) (*connect.Response[v1.BindDocCollectionResponse], error)
	UnbindDocCollection(context.Context, *connect.Request[v1.UnbindDocCollectionRequest]) (*connect.Response[v1.UnbindDocCollectionResponse], error)
	// 待决策清单：AI 开发的决策疑难点单向同步到一篇独立的 Outline 文档。
	SetDecisionDoc(context.Context, *connect.Request[v1.SetDecisionDocRequest]) (*connect.Response[v1.SetDecisionDocResponse], error)
	ClearDecisionDoc(context.Context, *connect.Request[v1.ClearDecisionDocRequest]) (*connect.Response[v1.ClearDecisionDocResponse], error)
	ListDecisionDocs(context.Context, *connect.Request[v1.ListDecisionDocsRequest]) (*connect.Response[v1.ListDecisionDocsResponse], error)
	ListDecisionSyncs(context.Context, *connect.Request[v1.ListDecisionSyncsRequest]) (*connect.Response[v1.ListDecisionSyncsResponse], error)
	// ReconcileDecisionSync 对 unknown / attempted 的条目做一次只读查证，绝不重写文档。
	ReconcileDecisionSync(context.Context, *connect.Request[v1.ReconcileDecisionSyncRequest]) (*connect.Response[v1.ReconcileDecisionSyncResponse], error)
	// ResolveDecisionSync 人工把 unknown 的条目结案为 delivered / cancelled，必须写明原因。
	ResolveDecisionSync(context.Context, *connect.Request[v1.ResolveDecisionSyncRequest]) (*connect.Response[v1.ResolveDecisionSyncResponse], error)
	// 合并队列（PLAN #28）：入队和移除等同于给 PR 加上、去掉 label kiln:merge。
	ListMergeQueue(context.Context, *connect.Request[v1.ListMergeQueueRequest]) (*connect.Response[v1.ListMergeQueueResponse], error)
	AddToMergeQueue(context.Context, *connect.Request[v1.AddToMergeQueueRequest]) (*connect.Response[v1.AddToMergeQueueResponse], error)
	RemoveFromMergeQueue(context.Context, *connect.Request[v1.RemoveFromMergeQueueRequest]) (*connect.Response[v1.RemoveFromMergeQueueResponse], error)
	// 自动打 tag（PLAN #29.4）：合并进默认分支的 commit 打 tag 的记录；失败或跳过的可以重试。
	ListAutoTags(context.Context, *connect.Request[v1.ListAutoTagsRequest]) (*connect.Response[v1.ListAutoTagsResponse], error)
	RetryAutoTag(context.Context, *connect.Request[v1.RetryAutoTagRequest]) (*connect.Response[v1.RetryAutoTagResponse], error)
	// Runner 自升级（PLAN #27.13）：管理员按台请求升级到 Runner 上报的最新版本。
	GetRunnerUpgrade(context.Context, *connect.Request[v1.GetRunnerUpgradeRequest]) (*connect.Response[v1.GetRunnerUpgradeResponse], error)
	// SetRunnerUpgradeRegistry 设置 Runner 查询和下载升级包用的 registry（空表示官方 registry）。
	SetRunnerUpgradeRegistry(context.Context, *connect.Request[v1.SetRunnerUpgradeRegistryRequest]) (*connect.Response[v1.SetRunnerUpgradeRegistryResponse], error)
	// RequestRunnerUpgrade 请求把一台 Runner 升级到它上报的最新版本；已有进行中的请求时返回那一个。
	RequestRunnerUpgrade(context.Context, *connect.Request[v1.RequestRunnerUpgradeRequest]) (*connect.Response[v1.RequestRunnerUpgradeResponse], error)
	// CancelRunnerUpgrade 取消一台 Runner 进行中（还没有切换）的升级请求。
	CancelRunnerUpgrade(context.Context, *connect.Request[v1.CancelRunnerUpgradeRequest]) (*connect.Response[v1.CancelRunnerUpgradeResponse], error)
	// CheckRunnerUpgrade 让 Runner 立即查询最新版本（runner 为空表示全部没有吊销的 Runner）。
	CheckRunnerUpgrade(context.Context, *connect.Request[v1.CheckRunnerUpgradeRequest]) (*connect.Response[v1.CheckRunnerUpgradeResponse], error)
	ListOutbox(context.Context, *connect.Request[v1.ListOutboxRequest]) (*connect.Response[v1.ListOutboxResponse], error)
	RetryOutbox(context.Context, *connect.Request[v1.RetryOutboxRequest]) (*connect.Response[v1.RetryOutboxResponse], error)
}

